TINY48 = '''from neural import xor_data, init_tiny, tiny_forward, tiny_loss_grads
X, y = xor_data()
parameters = init_tiny()
'''

L(2, '1. Separate unusual from confirmed harmful',
  'Define the reference population and investigation action before producing anomaly flags.',
  [('Anomaly score; investigation flag', 'A measure of difference from a reference. A flag requests investigation; it does not establish a confirmed fault, fraud or intent.'),
   ('Outlier versus novelty detection', 'Outlier analysis can fit a contaminated table. Novelty detection learns a reference, ideally normal, then screens later rows. The fitting assumptions differ.'),
   ('fault_split', 'Our helper simulates 320 normal fitting rows, 100 normal calibration rows and 200 evaluation rows with reserved injected-fault labels.')],
  "An unusually large reading might be a fault, a sensor-unit change or a valid rare event. The detection algorithm cannot decide its cause from unusualness alone. Define what a human will inspect, how outcomes will be confirmed and what a false alert costs.\n\nThis project assumes the fitting and calibration measurements are verified normal. That is an idealized teaching assumption, not something Isolation Forest automatically discovers. In a real system, contamination, delayed labels and operating-regime changes require a documented protocol.\n\nWe hold the injected evaluation answers aside until the detector and cutoff are fixed. Those labels allow a controlled audit of the simulation, but they do not validate operational fraud detection. No automatic punishment or customer restriction follows from a score.",
  'from lab import fault_split\nd = fault_split()\nprint("Fitting rows:", len(d["train"]))\nprint("Calibration rows:", len(d["calibration"]))\nprint("Evaluation rows:", len(d["evaluation"]))\nprint("Inputs:", d["train"].columns.tolist())\nprint("Action: inspect flagged measurements; confirm the cause separately")',
  'List two legitimate explanations for one unusually high temperature.',
  'for reason in ["a real equipment fault", "a unit or sensor calibration error", "a valid unusual operating condition"]:\n    print(reason)',
  'Write a reference contract without using evaluation labels.',
  'contract = {"fit": "verified-normal historical readings", "calibrate": "separate normal reference", "evaluate": "later paired measurements and confirmed outcomes", "flag_action": "human investigation"}\nfor role, meaning in contract.items():\n    print(role + ": " + meaning)',
  [('Does an anomaly flag confirm fraud or fault?', 'No', 'Always', 'Only if its score is large', 'Unusualness does not establish an underlying cause.'),
   ('Are normal-only fitting rows automatically guaranteed by the algorithm?', 'No; this is a data assumption to verify', 'Always', 'Only with 320 rows', 'The source and verification process establish reference quality.')],
  'Equate rare measurements with proven harmful behavior.', 'Define the reference and confirm causes through a separate investigation.',
  'The sizes define the teaching protocol. Evaluation labels have not selected a model or cutoff.',
  syntax='reference fit -> separate cutoff calibration -> frozen evaluation -> investigation')

L(2, '2. Start with a robust statistical screen',
  'Compute median absolute deviation and handle a zero-scale reference explicitly.',
  [('Median absolute deviation; MAD', 'The median of absolute differences from the median. It is less affected by extreme values than a mean/standard-deviation summary.'),
   ('Robust distance rule', 'Here abs(value-median)/MAD is a descriptive reference-scaled distance. It is not automatically a standard-normal z score or a probability.')],
  "A simple screen is often easier to audit than a complex model. Fit a median and MAD from allowed reference readings, then compare later values against a declared rule. Do not recompute the reference using the same suspicious readings merely to make them look ordinary.\n\nIf the reference is constant, MAD can be zero. Dividing by zero is not a meaningful detector. The appropriate response is an explicit domain policy, additional measurement resolution or a different reference; this lesson stops the calculation rather than silently inventing a tiny scale.\n\nA five-MAD threshold below is an illustrative screening rule, not a guaranteed false-alert rate. Seasonality, mixed operating regimes and correlated inputs can make a univariate rule miss important cases. Use it as a transparent baseline and check its actual outcomes.",
  'import numpy as np\nfrom lab import fault_split\nd = fault_split()\nreference = d["train"]["temperature_c"].to_numpy()\ncenter = np.median(reference)\nmad = np.median(np.abs(reference-center))\nif mad == 0:\n    raise ValueError("MAD is zero; define a reference policy")\nreadings = np.array([50., 60.])\ndistance = np.abs(readings-center)/mad\nprint("Median / MAD:", round(float(center), 2), round(float(mad), 2))\nprint("Robust distances:", distance.round(2).tolist())\nprint("Illustrative flags:", (distance > 5).tolist())',
  'Show why a constant reference cannot define a MAD denominator.',
  'import numpy as np\nr = np.array([7., 7., 7.])\nmad = np.median(np.abs(r-np.median(r)))\nprint("MAD:", float(mad))\nprint("Needs explicit zero-scale policy:", mad == 0)',
  'Compare a median and mean after adding one extreme observation.',
  'import numpy as np\na = np.array([49., 50., 50., 51., 200.])\nprint("Mean:", a.mean())\nprint("Median:", np.median(a))',
  [('Is this MAD-scaled distance automatically a calibrated fault probability?', 'No', 'Always', 'Only above five', 'A descriptive distance needs separate outcome validation.'),
   ('What should happen if MAD is zero?', 'Use an explicit documented policy rather than divide blindly', 'Always divide anyway', 'Label every row fraudulent', 'A zero reference scale cannot support that ratio.')],
  'Call a heuristic distance a guaranteed probability or hide a zero denominator.', 'State the scale, screening rule and edge-case policy.',
  'The robust distances compare readings with a fixed training reference. Their flags are illustrative investigation requests.',
  syntax='mad = median(abs(reference - median(reference)))\nrobust_distance = abs(new_value - center) / mad')

L(2, '3. Fit Isolation Forest and calibrate score direction',
  'Keep reference fitting, cutoff selection and evaluation answers separate.',
  [('IsolationForest', 'Randomly partitions measurements. Points isolated with short paths tend to look unusual relative to fitting data; the score is not a causal diagnosis.'),
   ('score_samples; contamination', 'sklearn score_samples is lower for more unusual observations. We negate it so larger means more unusual. contamination affects the built-in decision offset, not verified anomaly truth.'),
   ('Calibration quantile; strict cutoff', 'The project fixes the 98th percentile of separate normal calibration scores, then flags score greater than that value. This empirical rule has no automatic future-rate guarantee.')],
  "Multivariate unusualness can involve combinations rather than one extreme input. Isolation Forest provides a model-based reference score. Read its sign convention before sorting or applying thresholds; reversing the sign can invert your investigation queue.\n\nThe project fits 80 trees on normal fitting rows, obtains separate calibration scores and chooses a declared quantile. Evaluation answers do not select that cutoff. We use our own score>cutoff rule and do not confuse it with the estimator's default predict labels.\n\nThe 98th empirical quantile means a threshold chosen from this calibration sample. It does not promise exactly two percent of every future batch will be flagged, nor that two percent are truly faulty. Operating shifts and small calibration samples can change alert behavior.",
  'import numpy as np\nfrom sklearn.ensemble import IsolationForest\nfrom lab import fault_split\nd = fault_split()\nm = IsolationForest(n_estimators=80, contamination="auto", random_state=48, n_jobs=1).fit(d["train"])\nreference = -m.score_samples(d["calibration"])\ncutoff = float(np.quantile(reference, 0.98))\nscores = -m.score_samples(d["evaluation"])\nprint("Cutoff:", round(cutoff, 4))\nprint("Flagged evaluation rows:", int((scores > cutoff).sum()))\nprint("Score direction: larger is more unusual")',
  'Apply the declared strict cutoff to three scores.',
  'import numpy as np\nscores, cutoff = np.array([0.4, 0.6, 0.8]), 0.6\nprint("Flags:", (scores > cutoff).tolist())',
  'Verify calibration cannot modify the fitted trees through score_samples.',
  'import numpy as np\nfrom sklearn.ensemble import IsolationForest\nfrom lab import fault_split\nd = fault_split()\nm = IsolationForest(n_estimators=20, random_state=48, n_jobs=1).fit(d["train"])\nbefore = m.score_samples(d["train"])\nm.score_samples(d["calibration"])\nprint("Reference predictions unchanged:", bool(np.array_equal(before, m.score_samples(d["train"]))))',
  [('In our negated score convention, which score is more unusual?', 'A larger score', 'A smaller score', 'Always zero', 'We explicitly negate sklearn score_samples.'),
   ('Does the 98th calibration quantile guarantee a future false-alert rate?', 'No', 'Always', 'Only with 100 rows', 'It is an empirical reference rule under stated assumptions.')],
  'Reverse the score sign or choose the cutoff using final evaluation answers.', 'Declare score direction and calibrate before inspecting evaluation outcomes.',
  'The cutoff uses normal calibration only. The printed flag count alone says nothing about how many flags are confirmed faults.',
  syntax='cutoff = np.quantile(-detector.score_samples(calibration), 0.98)\nflag = -detector.score_samples(new_rows) > cutoff')

L(2, '4. Keep time-series screens strictly in the past',
  'Build a past-only rolling reference and recognize warm-up and regime changes.',
  [('shift(1); rolling window', 'shift moves the series so the current reading is excluded from its own historical reference. rolling then summarizes a declared number of earlier positions.'),
   ('Warm-up; regime change', 'Early positions may not have enough reference readings. A real operating change can produce many flags without every reading being a separate fault.')],
  "For sequential monitoring, a full-series mean uses the future and can conceal the very event you wanted to detect. At each position, calculate the reference only from readings available before that position. Sorting timestamps and defining elapsed-time versus row-count windows are separate responsibilities.\n\nThis small example uses an earlier three-position rolling median with at least three historical readings. Early references remain missing during warm-up. A threshold of four degrees is illustrative and requires a real measurement/error policy before operational use.\n\nPast-only computation does not by itself establish forecast quality or fault diagnosis. Seasonality and operating-regime changes may need contextual reference windows. Preserve order and future-label availability when evaluating a deployed monitor.",
  'import pandas as pd\ns = pd.Series([50., 50., 51., 50., 60., 51., 50.])\nreference = s.shift(1).rolling(3, min_periods=3).median()\nflag = reference.notna() & ((s-reference).abs() > 4)\nprint(pd.DataFrame({"reading": s, "past_median": reference, "flag": flag}).to_string(index=False))',
  'Verify adding future values does not change earlier past-only references.',
  'import pandas as pd\na = pd.Series([1., 2., 3., 4.])\nb = pd.concat([a, pd.Series([999.])], ignore_index=True)\nra = a.shift(1).rolling(2).mean()\nrb = b.shift(1).rolling(2).mean()\nprint("Earlier references unchanged:", ra.equals(rb.iloc[:len(a)]))',
  'Count the warm-up positions for a three-value historical window.',
  'import pandas as pd\ns = pd.Series([1., 2., 3., 4., 5.])\nref = s.shift(1).rolling(3, min_periods=3).median()\nprint("Warm-up positions:", int(ref.isna().sum()))',
  [('Why shift before calculating this reference?', 'To exclude the current reading from its own history', 'To include every future value', 'To change measurement units', 'The screen must use information available before its current observation.'),
   ('Does a three-position window always mean three hours?', 'No; row spacing determines elapsed time', 'Always', 'Only with pandas', 'Position and calendar-time windows are different contracts.')],
  'Normalize a full timeline using future values or treat warm-up as confirmed normal.', 'Use available history and record periods without a defined reference.',
  'The median is missing until three earlier values exist. The large reading is compared with its past, not a future-adjusted average.',
  syntax='past_reference = readings.shift(1).rolling(3, min_periods=3).median()')

L(2, '5. Audit anomaly flags against reserved outcomes',
  'Reconstruct false alerts and missed faults after freezing the cutoff.',
  [('Fault precision and recall', 'Precision asks what share of investigation flags are confirmed positives; recall asks what share of actual positives were flagged. Both depend on the evaluation population and target quality.')],
  "Once the cutoff is fixed, reveal the simulated evaluation outcomes and count errors. A detector that flags everything can achieve high recall while creating many false alerts. A detector that never flags avoids false alerts but misses every injected fault. Report both sides.\n\nThe plotted row order was randomly shuffled by the simulator; it is not a time axis. Colored markers reveal injected truth only for this audit, after fitting and calibration. Repeatedly changing the cutoff from this picture consumes the audit as development feedback.\n\nInjected faults are intentionally simple. Their precision and recall do not establish operational performance on subtle faults, new regimes or real fraud. Preserve the paired score, flag and actual outcome so the report can be reconstructed.",
  'import matplotlib.pyplot as plt\nimport numpy as np\nfrom lab import fit_fault_detector\nm, d, scores, flags, r = fit_fault_detector()\nc = r["evaluation"]\nprecision = c["tp"]/(c["tp"]+c["fp"]) if c["tp"]+c["fp"] else 0\nrecall = c["tp"]/(c["tp"]+c["fn"])\nprint("Audit counts:", c)\nprint("Precision / recall:", round(precision, 3), round(recall, 3))\nfig, ax = plt.subplots(figsize=(6.5, 3.2))\nfor actual, name, color in [(0, "Simulated normal", "#247ba0"), (1, "Injected fault", "#cf6e27")]:\n    mask = d["truth"] == actual\n    ax.scatter(np.flatnonzero(mask), scores[mask], label=name, color=color, s=16)\nax.axhline(r["cutoff"], color="#333333", linestyle="--", label="Frozen calibration cutoff")\nax.set(xlabel="Shuffled evaluation row position (not time)", ylabel="Unusualness: negative score_samples", title="Audit after freezing detector and cutoff")\nax.legend(fontsize=8)\nfig.tight_layout()\nfig.savefig("chart.png", dpi=110)\nplt.close(fig)',
  'Reconstruct the four audit counts from paired truth and flags.',
  'from sklearn.metrics import confusion_matrix\nfrom lab import fit_fault_detector\nm, d, scores, flags, r = fit_fault_detector()\nprint("TN FP FN TP:", confusion_matrix(d["truth"], flags, labels=[0, 1]).ravel().tolist())',
  'Compare never-flag behavior with the known simulation event count.',
  'from lab import fault_split\nd = fault_split()\nprint("Never-flag false alerts:", 0)\nprint("Never-flag missed injected faults:", int(d["truth"].sum()))',
  [('When may evaluation labels select this cutoff?', 'They must not; cutoff selection already finished', 'After every score plot', 'Only for 40 faults', 'The audit must assess the frozen procedure.'),
   ('Does the horizontal position represent time?', 'No; these evaluation rows were shuffled', 'Always', 'Only for normal rows', 'The figure explicitly plots row position, not a timeline.')],
  'Tune from the audit picture or report recall while hiding false alerts.', 'Preserve the frozen decision rule and report paired error counts.',
  'The labels are used only for the post-selection audit. The picture makes false alerts and missed injected faults inspectable.',
  syntax='tn, fp, fn, tp = confusion_matrix(actual, flag, labels=[0, 1]).ravel()',
  figure=('Frozen anomaly scores and injected evaluation outcomes with a calibration cutoff', 'Horizontal position is shuffled row order, not time. Truth colors are revealed only for audit; the cutoff came from separate normal calibration.'))

L(2, '6. Design a human investigation and monitoring loop',
  'Prioritize finite review capacity and distinguish drift, labels and new evaluation.',
  [('Review capacity; top-score queue', 'A bounded investigation list can be ordered by score. A queue is a resource policy, not a new truth label or a guaranteed anomaly count.'),
   ('Outcome feedback loop', 'Record confirmed findings and delays, investigate alert changes, and evaluate any revised detector on suitable fresh evidence.')],
  "An operational detector needs an action process. Who reviews a flag, what evidence confirms a fault, how quickly is it available and what happens if the alert queue exceeds capacity? These questions matter as much as a model score.\n\nThe example orders the largest unusualness scores for a five-item review capacity. It does not call those five observations confirmed faulty. A threshold can flag more or fewer than the capacity, so record unresolved work rather than silently treating unreviewed cases as normal.\n\nMonitor units, missingness, score distributions, review backlog and later confirmed outcomes. If a new operating regime requires retraining or recalibration, record a new version and evaluate it honestly. Reusing an already inspected audit is not fresh evidence.",
  'import numpy as np\nfrom lab import fit_fault_detector\nm, d, scores, flags, r = fit_fault_detector()\nqueue = np.flatnonzero(flags)\nqueue = queue[np.argsort(scores[queue])[::-1]]\ncapacity = 5\nprint("Flagged rows:", len(queue))\nprint("Review positions:", queue[:capacity].tolist())\nprint("Pending reviews:", max(0, len(queue)-capacity))\nprint("A queue position is not a confirmed fault label")',
  'Define three statuses without collapsing pending review into normal.',
  'statuses = ["pending investigation", "confirmed fault", "confirmed non-fault"]\nfor status in statuses:\n    print(status)',
  'Write a version-change rule after recalibrating from new information.',
  'print("Record the new reference, cutoff, rationale and model version")\nprint("Evaluate on suitable cases that did not guide the revision")\nprint("Retain the earlier report as historical evidence")',
  [('Are the top five scores automatically five confirmed faults?', 'No', 'Always', 'Only with capacity five', 'Ranking allocates investigation capacity rather than verifying outcomes.'),
   ('Should unreviewed flags become normal labels automatically?', 'No', 'Always', 'Only after one day', 'Pending confirmation is different from a verified negative.')],
  'Treat a review-capacity limit as the true anomaly count.', 'Track flags, unresolved reviews and confirmed outcomes separately.',
  'The queue is derived from the fixed detector rule and ordered scores. Its size is a workload fact, not confirmed incident prevalence.',
  syntax='review_queue = flagged_positions[descending_score_order]')

L(3, '1. Build a two-layer network from arrays',
  'Trace input, hidden and output shapes before attempting training.',
  [('Neuron; affine layer; weight; bias', 'A layer computes X @ W + b. Weights multiply inputs; bias shifts each output. A neuron is one output coordinate, not a literal brain cell.'),
   ('Hidden layer; activation', 'A nonlinear activation between affine layers lets the composition represent more than one affine transformation.'),
   ('xor_data; init_tiny; tiny_forward', 'Supplied NumPy helpers define four XOR cases, initialize a 2 → 4 → 1 network, and return hidden values, output logits and probabilities.')],
  "Start with four two-input cases. XOR is positive when the signs differ and negative when they match. This tiny pattern is useful because a single straight-line decision boundary cannot separate its four corners. It is a mechanics exercise, not a realistic deployment dataset.\n\nOur first weight matrix has shape 2 by 4, producing four hidden values per case. The second has shape 4 by 1, producing one binary output per case. Bias vectors broadcast across rows. Write these shapes down before debugging gradients.\n\nWe use tanh in the hidden layer and a sigmoid at the binary output. The next part explains their role. No training occurs in this forward pass; initialized parameters are only a starting point.",
  TINY48 + 'hidden, logits, probability = tiny_forward(X, parameters)\nprint("Input:", X.shape)\nprint("W1 / W2:", parameters["W1"].shape, parameters["W2"].shape)\nprint("Hidden:", hidden.shape)\nprint("Logits / target:", logits.shape, y.shape)\nprint("Initial probabilities:", probability.ravel().round(3).tolist())',
  'Count all trainable scalar values in this tiny network.',
  'from neural import init_tiny\np = init_tiny()\nprint("Parameter counts:", {name: value.size for name, value in p.items()})\nprint("Total:", sum(value.size for value in p.values()))',
  'Construct one affine layer and verify broadcasting preserves the batch dimension.',
  'import numpy as np\nX = np.ones((3, 2))\nW, b = np.ones((2, 4)), np.zeros(4)\nprint("Batch output:", (X @ W + b).shape)',
  [('What is the first weight-matrix shape for two inputs and four hidden outputs?', '(2, 4)', '(4, 2) in X @ W', '(2, 1)', 'The inner matrix dimensions must match.'),
   ('Are these initialized predictions trained evidence?', 'No', 'Always', 'Only if they exceed 0.5', 'A forward pass alone does not learn parameters.')],
  'Start a training loop without checking shapes or call initialization a learned result.', 'Trace every array dimension before fitting.',
  'The output and target both have shape (4, 1), preventing accidental broadcasting into a different loss table.',
  syntax='hidden = activation(X @ W1 + b1)\nlogits = hidden @ W2 + b2')

L(3, '2. Explain nonlinearity, logits and stable loss',
  'Separate raw output, binary probability and the optimization objective.',
  [('tanh; sigmoid/expit', 'tanh maps hidden values between -1 and 1. The sigmoid maps a binary logit to a value between zero and one.'),
   ('Binary cross-entropy from logits', 'For label y in {0,1}, logaddexp(0,z)-y*z computes a numerically stable logistic loss without taking log of a rounded zero probability.'),
   ('Logit versus thresholded flag', 'The raw real-valued score becomes a probability through sigmoid, then an optional decision through a threshold. These are distinct objects.')],
  "Stacking two affine layers without an intervening nonlinearity still produces an affine function. The hidden activation is what lets the network represent nonlinear patterns such as XOR. Choosing an activation changes the function and its gradient behavior.\n\nThe binary output is a logit z. Sigmoid turns it into a probability-like model output. Training minimizes average binary cross-entropy. Do not confuse a lower loss with a proven improvement on unseen cases; training and evaluation boundaries still apply.\n\nA naive log(sigmoid(z)) can become numerically troublesome for extreme logits. The stable formula avoids explicitly logging a rounded zero. This numerical repair does not establish that the probabilities are calibrated in a real population.",
  'import numpy as np\nfrom scipy.special import expit\nz = np.array([-1000., 0., 1000.])\ny = np.array([0., 1., 1.])\nlosses = np.logaddexp(0, z)-y*z\nprint("Probabilities:", expit(z).tolist())\nprint("Finite loss:", bool(np.isfinite(losses).all()))\nprint("Losses:", losses.round(3).tolist())',
  'Evaluate sigmoid and tanh at zero and describe their different output roles.',
  'import numpy as np\nfrom scipy.special import expit\nprint("Hidden tanh at zero:", float(np.tanh(0)))\nprint("Binary probability at zero logit:", float(expit(0)))',
  'Show two affine operations collapse to another affine operation.',
  'import numpy as np\nX = np.array([[1., 2.]])\nW1, b1 = np.array([[1.], [2.]]), np.array([3.])\nW2, b2 = np.array([[4.]]), np.array([5.])\nprint("Same affine result:", bool(np.allclose((X@W1+b1)@W2+b2, X@(W1@W2)+b1@W2+b2)))',
  [('What creates nonlinear capacity between these affine layers?', 'The hidden nonlinear activation', 'Only naming two layers', 'Only an extra bias', 'Without it, affine compositions remain affine.'),
   ('Does a stable logistic loss prove probability calibration?', 'No', 'Always', 'Only for XOR', 'Numerical stability and population calibration are different properties.')],
  'Take logs of rounded zero probabilities or confuse logits with calibrated real-world probabilities.', 'Use stable loss arithmetic and keep output meanings separate.',
  'Even extreme logits produce finite losses here. That checks numerical behavior, not predictive generalization.',
  syntax='loss = np.mean(np.logaddexp(0, logits) - target * logits)')

L(3, '3. Derive backpropagation through the two layers',
  'Use the chain rule to calculate each parameter gradient with correct averaging.',
  [('Backpropagation; chain rule', 'Propagates the loss derivative backward through each operation. It efficiently computes gradients; the optimizer then uses them to change parameters.'),
   ('Gradient; derivative shapes', 'A gradient has one derivative per parameter coordinate. For our mean binary loss, output-logit derivative is (probability-target)/number_of_rows.'),
   ('tanh derivative', 'If h=tanh(a), then dh/da=1-h². The hidden gradient multiplies this local derivative after propagating through the output weights.'),
   ('tiny_loss_grads', 'Our NumPy helper returns a stable mean binary loss and a dictionary of the four parameter gradients. It calculates derivatives without changing parameters.')],
  "Let H=tanh(XW1+b1), z=HW2+b2 and p=sigmoid(z). The mean loss derivative with respect to z is (p-y)/n. Then dW2=H.T@dz and db2 is the sum of dz over rows.\n\nMove backward through W2 and tanh: da=(dz@W2.T)*(1-H²). Finally dW1=X.T@da and db1 is the row sum of da. Every gradient must match its parameter shape. We divide by n once at dz, not again at every layer.\n\nThe supplied helper implements these equations directly in NumPy. It does not invoke an automatic differentiation framework. We inspect its shapes and then independently check numerical derivatives in the next part.",
  TINY48 + 'loss, gradients = tiny_loss_grads(X, y, parameters)\nprint("Initial mean loss:", round(loss, 4))\nfor name in parameters:\n    print(name, "parameter", parameters[name].shape, "gradient", gradients[name].shape)\nprint("Rows averaged:", len(X))',
  'Reproduce the output-layer gradients directly from the forward pass.',
  TINY48 + 'import numpy as np\nH, z, p = tiny_forward(X, parameters)\ndz = (p-y)/len(X)\nloss, g = tiny_loss_grads(X, y, parameters)\nprint("W2 derivative parity:", bool(np.allclose(H.T@dz, g["W2"])))\nprint("b2 derivative parity:", bool(np.allclose(dz.sum(axis=0), g["b2"])))',
  'Verify the tanh derivative at zero and at a nonzero activation.',
  'import numpy as np\na = np.array([0., 2.])\nh = np.tanh(a)\nprint("tanh derivatives:", (1-h**2).round(4).tolist())',
  [('Which operation changes weights after gradients are calculated?', 'The optimizer update', 'Backpropagation alone without an update', 'The test labels', 'Gradients describe a direction; an explicit update performs learning.'),
   ('How many times is averaging by n applied in these equations?', 'Once at the output derivative', 'Once at every multiplication', 'Never', 'Repeated averaging would incorrectly shrink later derivatives.')],
  'Multiply incompatible shapes or divide by the batch size again at every layer.', 'Derive each operation and match gradients to parameter shapes.',
  'All four gradients match their parameter arrays. Output-layer parity checks the stated algebra before optimization.',
  syntax='dz = (probability - target) / len(X)\ndW2 = hidden.T @ dz\nda = (dz @ W2.T) * (1 - hidden**2)\ndW1 = X.T @ da')

L(3, '4. Verify gradients with independent finite differences',
  'Compare analytic derivatives with a small central perturbation.',
  [('Central finite difference', 'Approximates a derivative with [loss(w+eps)-loss(w-eps)]/(2*eps). It is slower than backpropagation but useful for checking a tiny implementation.'),
   ('Numerical tolerance', 'Finite differences combine approximation and floating-point error. Extremely tiny eps can make subtraction error worse rather than more accurate.')],
  "A decreasing loss does not prove every gradient is correct. A bug can still produce occasional improvement. Check a tiny network by perturbing one parameter while holding all others fixed and compare the resulting slope with the analytic derivative.\n\nThe example checks the first W1 coordinate with eps=1e-5. The practice solution checks all 17 coordinates across W1, b1, W2 and b2. It uses separate copies so the perturbation does not permanently change the original parameters.\n\nThis method is an authoring/debugging check, not the normal training algorithm for a large network. Framework autograd is much more efficient for computing many derivatives, but it still needs the correct forward computation and objective.",
  TINY48 + 'import numpy as np\n_, gradients = tiny_loss_grads(X, y, parameters)\neps = 1e-5\na = {k: v.copy() for k, v in parameters.items()}\nb = {k: v.copy() for k, v in parameters.items()}\na["W1"][0, 0] += eps\nb["W1"][0, 0] -= eps\nnumerical = (tiny_loss_grads(X, y, a)[0]-tiny_loss_grads(X, y, b)[0])/(2*eps)\nprint("Analytic:", round(float(gradients["W1"][0, 0]), 7))\nprint("Numerical:", round(numerical, 7))\nprint("Agreement:", bool(np.isclose(numerical, gradients["W1"][0, 0], atol=1e-8)))',
  'Check every parameter coordinate and report the maximum absolute difference.',
  TINY48 + 'import numpy as np\n_, g = tiny_loss_grads(X, y, parameters)\nerrors = []\neps = 1e-5\nfor name, value in parameters.items():\n    for index in np.ndindex(value.shape):\n        a = {k: v.copy() for k, v in parameters.items()}\n        b = {k: v.copy() for k, v in parameters.items()}\n        a[name][index] += eps\n        b[name][index] -= eps\n        numerical = (tiny_loss_grads(X, y, a)[0]-tiny_loss_grads(X, y, b)[0])/(2*eps)\n        errors.append(abs(numerical-g[name][index]))\nprint("Coordinates checked:", len(errors))\nprint("All within tolerance:", max(errors) < 1e-8)',
  'Verify the analytic-gradient helper does not mutate parameters.',
  TINY48 + 'import numpy as np\nbefore = {k: v.copy() for k, v in parameters.items()}\ntiny_loss_grads(X, y, parameters)\nprint("No parameter mutation:", all(np.array_equal(before[k], parameters[k]) for k in parameters))',
  [('Why use separate perturbation copies?', 'To keep the original parameter state unchanged', 'To increase dataset size', 'To improve test accuracy', 'A numerical check should not silently train or corrupt the model.'),
   ('Is the smallest possible eps always best?', 'No', 'Always', 'Only for W1', 'Subtraction and floating-point error compete with approximation error.')],
  'Assume a falling loss proves all derivatives correct.', 'Independently compare finite differences with analytic gradients.',
  'The check perturbs only one coordinate at a time. The full exercise verifies all 17 analytic derivatives.',
  syntax='numerical_gradient = (loss_at_plus_eps - loss_at_minus_eps) / (2 * eps)')

L(3, '5. Train XOR with explicit gradient-descent updates',
  'Observe loss reduction while keeping training evidence separate from generalization.',
  [('Learning rate; gradient descent', 'The update parameter -= rate*gradient moves against the local loss slope. Too large a rate can destabilize training; too small a rate can make progress slow.'),
   ('train_tiny; optimization step', 'Our helper repeats full-batch forward/loss/backprop/update for 1600 steps at rate0.2, using all four XOR training cases.')],
  "The training loop alternates calculation and change. First compute the current loss and gradients, then update every parameter with the same declared learning rate. Recompute the next loss from the new state. Do not accidentally train with stale gradients from an earlier parameter configuration.\n\nThe curve shows training loss over optimization steps. All four XOR cases are used repeatedly; there is no separate evaluation set in this mechanics example. Correctly classifying these four corners demonstrates representation and optimization, not broad generalization.\n\nA larger network is not needed to understand this loop. Start with a small transparent system, test gradients, and carry the same information-boundary discipline into the framework exercise on a standard dataset.",
  'import matplotlib.pyplot as plt\nfrom neural import xor_data, train_tiny, tiny_forward\nX, y = xor_data()\np, losses = train_tiny()\nprobability = tiny_forward(X, p)[2]\nprint("Initial / final training loss:", round(float(losses[0]), 4), round(float(losses[-1]), 4))\nprint("Training predictions:", (probability >= 0.5).astype(int).ravel().tolist())\nprint("Training targets:", y.astype(int).ravel().tolist())\nfig, ax = plt.subplots(figsize=(6.2, 3.1))\nax.plot(range(len(losses)), losses, color="#247ba0")\nax.set(xlabel="Full-batch optimization step", ylabel="Mean binary cross-entropy", title="Four XOR training cases; no generalization claim")\nfig.tight_layout()\nfig.savefig("chart.png", dpi=110)\nplt.close(fig)',
  'Perform one gradient update and compare the loss immediately before and after.',
  TINY48 + 'before, g = tiny_loss_grads(X, y, parameters)\nfor name in parameters:\n    parameters[name] -= 0.2*g[name]\nafter, _ = tiny_loss_grads(X, y, parameters)\nprint("Loss decreased on this step:", after < before)',
  'Confirm training predictions match all four seen XOR labels.',
  'import numpy as np\nfrom neural import xor_data, train_tiny, tiny_forward\nX, y = xor_data()\np, _ = train_tiny()\nprint("All four training cases:", bool(np.array_equal(tiny_forward(X, p)[2] >= 0.5, y.astype(bool))))',
  [('Do four memorized XOR cases establish handwriting generalization?', 'No', 'Always', 'Only after 1600 steps', 'The toy training exercise has a much narrower evidence scope.'),
   ('Which direction does gradient descent use?', 'Against the gradient of the objective', 'Always toward larger loss', 'Toward the final test labels', 'The update subtracts rate times the current gradient.')],
  'Describe a low toy training loss as unseen-data performance.', 'Report it as a checked training-mechanics demonstration.',
  'The network learns the four seen XOR corners. The loss chart is explicitly training evidence.',
  syntax='for step in range(steps):\n    loss, gradients = tiny_loss_grads(X, y, parameters)\n    for name in parameters:\n        parameters[name] -= rate * gradients[name]',
  figure=('NumPy XOR network training loss across gradient-descent steps', 'All four displayed cases are training cases. The curve demonstrates checked optimization, not independent predictive performance.'))

L(3, '6. Carry the same discipline into automatic differentiation',
  'Distinguish the forward model, derivative engine, optimizer and evaluation protocol.',
  [('Autograd', 'Automatic differentiation records supported tensor operations and calculates their derivatives. It does not choose the right target, split or model for you.'),
   ('Batch, epoch and step', 'A batch is a group of examples used in one update. An epoch visits the training dataset once; a step is one optimizer update. They are not interchangeable counts.'),
   ('digits_split', 'The local helper loads bundled digits, makes separate stratified training/validation/test rows, fits scaling on training only and returns prepared features, integer targets and original row ids.')],
  "NumPy made the derivatives visible. A deep-learning framework computes those derivatives automatically, but the same responsibilities remain: define the forward computation, objective, allowed training rows, update rule and evaluation process. Autograd faithfully differentiates a mistaken objective too.\n\nWith 1,077 training examples and batches of 128, an epoch has nine updates, including a smaller last batch. Forty-five epochs can therefore perform 405 updates. This is different from the four-case full-batch XOR loop, where every step uses the entire training set.\n\nThe next day uses a separate validation split to choose a copied checkpoint, then inspects final test outcomes after that choice. No framework feature removes the need for these boundaries. GPU availability also does not automatically make a small task faster.",
  'import math\nfrom neural import digits_split\nd = digits_split()\nn = len(d["y_train"])\nbatch_size, epochs = 128, 45\nsteps_per_epoch = math.ceil(n/batch_size)\nprint("Training examples:", n)\nprint("Updates per epoch:", steps_per_epoch)\nprint("Updates for fixed epoch budget:", steps_per_epoch*epochs)',
  'Assign the four responsibilities to the right objects.',
  'roles = {"forward model": "compute logits", "loss": "define objective", "autograd": "differentiate supported operations", "optimizer": "update parameters"}\nfor name, role in roles.items():\n    print(name + ": " + role)',
  'Explain why a framework cannot repair a leaked evaluation split.',
  'print("Autograd computes derivatives of the supplied computation")\nprint("It does not know which rows were supposed to remain untouched")',
  [('Is an epoch always one optimizer update?', 'No; it can contain many batches and updates', 'Always', 'Only on CPU', 'The number of updates depends on training size and batch size.'),
   ('Does autograd guarantee a correct data split?', 'No', 'Always', 'Only with deterministic algorithms', 'Evaluation design is a separate responsibility.')],
  'Treat frameworks or GPU hardware as substitutes for a correct learning procedure.', 'Keep model, loss, derivatives, updates and evaluation roles explicit.',
  'The step count follows the actual bundled-digits training size, not an assumed round number.',
  syntax='updates_per_epoch = ceil(number_of_training_rows / batch_size)')
